-- CampusMap N-01: datos geográficos académicos UAO.
-- Fuente de POI: docs/maps/map_uao.geojson; senderos: docs/maps/uao_senderos_overpass.geojson (ODbL).
-- Caminos OSM = segmentos mapeados; conexiones simulated = enlaces rectos APROXIMADOS, no senderos verificados.
-- Generado por scripts/generate-uao-navigation.mjs. No editar manualmente.
begin;
on conflict (id) do update set name = excluded.name, description = excluded.description, x = excluded.x, y = excluded.y, is_public = excluded.is_public;
-- Segmentos de senderos mapeados en OSM.
on conflict (id) do update set weight = excluded.weight, is_bidirectional = excluded.is_bidirectional, is_public = excluded.is_public;
-- Conexiones SIMULADAS: líneas rectas aproximadas, solo para fines académicos.
on conflict (id) do update set weight = excluded.weight, is_bidirectional = excluded.is_bidirectional, is_public = excluded.is_public;
commit;
